<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CRM — Lex Factum</title><link rel="stylesheet" href="<?= base_url('styles.css') ?>"><style>.crm-wrap{max-width:1200px;margin:110px auto 60px;padding:0 24px}.crm-nav{display:flex;gap:10px;flex-wrap:wrap;margin:20px 0}.crm-nav a,.crm-btn{display:inline-block;padding:11px 16px;border:1px solid rgba(180,150,95,.35);border-radius:10px;color:inherit;text-decoration:none}.crm-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}.crm-card{padding:22px;border:1px solid rgba(180,150,95,.22);border-radius:16px;background:rgba(255,255,255,.04)}.crm-card strong{display:block;font-size:2rem;margin-top:8px}.crm-table{width:100%;border-collapse:collapse;margin-top:16px}.crm-table th,.crm-table td{padding:12px;border-bottom:1px solid rgba(180,150,95,.18);text-align:left}.crm-table a{color:inherit}.flash{padding:12px 15px;border-radius:10px;margin:12px 0;background:rgba(180,150,95,.12)}</style></head><body><div class="crm-wrap"><div class="eyebrow">Admin · CRM</div><h1>Client & Matter Management</h1><div class="crm-nav"><a href="<?= site_url('admin') ?>">← Admin</a><a href="<?= site_url('admin/crm/clients') ?>">Clients</a><a href="<?= site_url('admin/crm/cases') ?>">Cases</a></div><?php if(session()->getFlashdata('message')): ?><div class="flash"><?= esc(session()->getFlashdata('message')) ?></div><?php endif; ?><div class="crm-grid"><div class="crm-card">Clients<strong><?= $clientCount ?></strong></div><div class="crm-card">Active Clients<strong><?= $activeClientCount ?></strong></div><div class="crm-card">Cases<strong><?= $caseCount ?></strong></div><div class="crm-card">Open Cases<strong><?= $openCaseCount ?></strong></div></div><h2 style="margin-top:42px">Recent Clients</h2><table class="crm-table"><tr><th>Name</th><th>Email</th><th>Phone</th><th>Status</th></tr><?php foreach($recentClients as $c): ?><tr><td><?= esc($c['name']) ?></td><td><?= esc($c['email']) ?></td><td><?= esc($c['phone']) ?></td><td><?= esc($c['status']) ?></td></tr><?php endforeach; ?></table><h2 style="margin-top:42px">Recent Cases</h2><table class="crm-table"><tr><th>Case</th><th>Client</th><th>Court</th><th>Status</th></tr><?php foreach($recentCases as $c): ?><tr><td><?= esc($c['title']) ?></td><td>#<?= esc($c['client_id']) ?></td><td><?= esc($c['court']) ?></td><td><?= esc($c['status']) ?></td></tr><?php endforeach; ?></table></div></body></html>
